import{_ as i,o as r,c as a,j as e,a as n,aa as s}from"./chunks/framework.BAs_AphD.js";const d="/buildary-help-preview/media/en/diary/en_dennizaznamydalsizaznamy.jpg",l="/buildary-help-preview/media/en/diary/en_dennizaznamydalsizaznamy2.jpg",h="/buildary-help-preview/media/en/diary/en_dalsi_volby_dalsizaznamy.jpg",c="/buildary-help-preview/media/en/diary/en_reakce_na_zaznam.jpg",o="/buildary-help-preview/media/en/diary/en_indikacni_ikony_dalsizaznamy.jpg",p="/buildary-help-preview/media/en/diary/en_souvisejici_zaznamy.jpg",g="/buildary-help-preview/media/en/diary/en_odeslat_zpravu.jpg",k=JSON.parse('{"title":"Daily Entries - Other Entries","description":"","frontmatter":{"title":"Daily Entries - Other Entries","wiki":"en:diary:dailyentriesothers"},"headers":[],"relativePath":"en/diary/dailyentriesothers.md","filePath":"en/diary/dailyentriesothers.md","lastUpdated":1794388980000}'),y={name:"en/diary/dailyentriesothers.md"};function u(f,t,m,b,w,v){return r(),a("div",null,[...t[0]||(t[0]=[e("h1",{id:"daily-entries-other-entries",tabindex:"-1"},[n("Daily Entries - Other Entries "),e("a",{class:"header-anchor",href:"#daily-entries-other-entries","aria-label":'Permalink to "Daily Entries - Other Entries"'},"​")],-1),e("h3",{id:"video-for-the-other-entries-section",tabindex:"-1"},[n("Video for the Other Entries section "),e("a",{class:"header-anchor",href:"#video-for-the-other-entries-section","aria-label":'Permalink to "Video for the Other Entries section"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/0-e_jr07kEI",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<h2 id="other-entries" tabindex="-1">Other Entries <a class="header-anchor" href="#other-entries" aria-label="Permalink to &quot;Other Entries&quot;">​</a></h2><p>All authorized persons can add records to this section. A new record is added using the <strong>+ New record</strong> button.</p><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="" width="600" loading="lazy"></figure><p>In the <strong>New Other Entry</strong> window, you can enter text of any length in the <strong>Description</strong> field.</p><p>The <strong>Category</strong> field is linked to a reference list that allows records to be divided into groups or filtered.</p><p>The <strong>Specification</strong> field is used to provide a more detailed designation of the record for subsequent filtering.</p><p>Attachments of any format can be uploaded to the record. When adding attachments, we recommend adjusting the size and number of attachments to the quality of your internet connection. The larger the files, the more problems may occur when downloading them or uploading a signed report. The size of a single file must not exceed 30 MB.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Please note <strong>compressed files</strong> such as ZIP, RAR, ARJ, etc. Most <strong>free</strong> versions of PDF editors do not allow attachments in compressed formats to be downloaded from a PDF file. We therefore do not recommend adding compressed files as attachments. A domain Administrator can disable the uploading of these file types in the Domain Settings.</p></div><p>In the Project Diary Settings, you can enable the <strong>Location</strong> and <strong>Drawing</strong> fields. This allows the record to additionally be localized using GPS coordinates on a map and/or on a drawing uploaded in the Project Settings.</p><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="" width="600" loading="lazy"></figure><p>Other Entries always display the <strong>Author</strong> of the record and their role in the diary.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The author should also sign their own records, thereby locking them. If they do not have a signing certificate, a scan of the signed report can be uploaded to lock the record. Details regarding signing Other Records reports are described in a separate section of the documentation.</p></div><h2 id="other-options" tabindex="-1">Other Options <a class="header-anchor" href="#other-options" aria-label="Permalink to &quot;Other Options&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+h+'" alt="" width="600" loading="lazy"></figure><p>The <strong>Other options</strong> button is available in the upper-right corner of each entry and provides various options for working with the entry. The most frequently used functions are displayed in the entry header as separate buttons.</p><p><strong>Edit</strong> can only be used by the author of the entry and only until the entry has been signed or a response has been created for it.</p><p><strong>Diary entry preview</strong> - displays the entry in PDF format in the browser.</p><p><strong>Download for digital signature</strong>, <strong>Upload digitally signed file</strong>, and <strong>Upload scan of this report</strong> are related to signing or locking the entry and are explained in a separate section.</p><p><strong>Respond</strong> - this option creates a response to the selected entry and links it to that entry. More information about this functionality is provided below.</p><p><strong>Related entries</strong> - this option is inactive until a response has been created for the entry. It is used to display the thread containing the original record and all responses belonging to it.</p><p><strong>List of recipients</strong> allows you to send a notification about the added entry by email to any authorized person in the diary. See below for more information.</p><p><strong>New task for this diary entry</strong> and <strong>Ticket related to this entry</strong> are related to the Ticket Management module and are described in a separate section.</p><p><strong>Delete</strong> can only be used by the author of the entry and only until the entry has been signed or a response has been created for it. If an unsigned entry that already has a response needs to be deleted, the response must first be deleted, followed by the relevant entry.</p><h3 id="respond-and-related-records" tabindex="-1">Respond and Related Records <a class="header-anchor" href="#respond-and-related-records" aria-label="Permalink to &quot;Respond and Related Records&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+c+'" alt="" width="600" loading="lazy"></figure><p>When <strong>Respond</strong> is selected, the <strong>The entry you want to respond to</strong> window opens for editing the response. The upper part of the window displays the complete entry you are responding to, with the editing fields below it.</p><p>The author enters their response in the <strong>Description</strong> field.</p><p>The contents of the <strong>Contractor Name</strong>, <strong>Category</strong>, and <strong>Specification</strong> fields are automatically copied from the original record by default.</p><p>In the <strong>Date where response will be saved</strong> field, the application automatically sets the current date. The date can be changed using the calendar icon. The displayed calendar only offers days on which the response can actually be entered. If previous days have not yet been signed, the response can be entered on one of those previous days, but no later than the day containing the entry to which you are responding.</p><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="" width="600" loading="lazy"></figure><p>A yellow <strong>Related entries</strong> icon indicates that a response has been added to an entry. The number indicates how many responses have been made to the entry. Clicking the icon opens the <strong>Other entry response tree</strong> window.</p><figure class="shot" style="--w:600px;"><img src="'+p+'" alt="" width="600" loading="lazy"></figure><p>The <strong>Other entry response tree</strong> window displays all entries that are related to one another, meaning they were created using the <strong>Respond</strong> option. The current entry is always highlighted with a blue header, and all preceding and subsequent records in the thread are visible.</p><h3 id="sending-an-email-and-message-recipients" tabindex="-1">Sending an Email and Message Recipients <a class="header-anchor" href="#sending-an-email-and-message-recipients" aria-label="Permalink to &quot;Sending an Email and Message Recipients&quot;">​</a></h3><figure class="shot" style="--w:400px;"><img src="'+g+'" alt="" width="600" loading="lazy"></figure><p>Due to the nature of the Other Entries section, a quick response from the other party is often required. To ensure that the relevant person is informed about an entry in time, an email notification function is available through the <strong>List of recipients</strong> option in the Other options menu.</p><p>The <strong>Notification of Other entry</strong> window opens with a list of all authorized persons. By checking the box on the left, you can send a message by email to any person on the list, including sending notifications repeatedly.</p><p>Any person&#39;s info can be opened from the list to display their email address and role. For people who have been sent a notification, the date and time when it was sent are also displayed.</p><p>People who have been invited to the project by the Project Administrator but have not yet created an account in the application are marked with a red exclamation mark.</p><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="" width="600" loading="lazy"></figure><p>A purple <strong>Message recipients</strong> icon in the record indicates that a notification has been sent. The number indicates how many people received the notification. Clicking the icon opens the <strong>Notification of Other entry</strong> window. For all recipients who have received the notification email, the envelope icon on the left is displayed in blue.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Notifications can be sent <strong>automatically</strong> by checking the <strong>Other Entry E-mail Notification</strong> option in <strong>Diary Identification -&gt; Authorized Persons</strong>, in the editing window for the relevant person. This person must be allowed to use this function by selecting <strong>According to Diary settings</strong> under <strong>Project Settings -&gt; Project Team -&gt; &quot;Email notification - Project Diary&quot;</strong>.</p></div>',42)])])}const z=i(y,[["render",u]]);export{k as __pageData,z as default};
